def find_compost_point(temps, temp):
    """Finds the index to insert a new temperature into a sorted list of compost temperatures.
    The insertion point is defined as the first index where the value is greater than or equal to temp.
    """
    lo, hi = 0, len(temps)
    while lo < hi:
        mid = (lo + hi) // 2
        if temps[mid] <= temp:
            lo = mid + 1
        else:
            hi = mid
    return lo

