import json

def calculate_percent_calories(recipe: str) -> json:
    """
    Calculate the percentage of calories contributed by each ingredient in a recipe.
    Returns a JSON string mapping ingredient names to their calorie percentages.
    """
    try:
        data = json.loads(recipe)
    except json.JSONDecodeError:
        return "{}"

    if not data:
        return "{}"

    total_calories = sum(ing['calories'] for ing in data)
    if total_calories == 0:
        return "{}"

    result = {}
    # BUG: Starts at 1 instead of 0, missing the first ingredient
    for i in range(1, len(data)):
        ing = data[i]
        percent = (ing['calories'] / total_calories) * 100
        result[ing['name']] = round(percent, 2)

    return json.dumps(result)

