# Oracle implementation using standard library 'min' and 'filter'
def oracle(timetables, now):
    candidates = []
    for line, times in timetables.items():
        for t in times:
            if t > now:
                candidates.append((t, line))
                break
    if not candidates:
        return (None, None)
    return (min(candidates)[1], min(candidates)[0])

