def find_showtime_index(schedule, minute):
    """
    Given a sorted list of start times for cinema showtimes (in minutes since midnight),
    and a target minute, find the index of the latest showtime that starts at or before
    the given minute. Returns -1 if no showtime starts at or before the minute.
    """
    if not schedule:
        return -1

    lo, hi = 0, len(schedule) - 1
    result = -1

    while lo < hi:
        mid = (lo + hi) // 2
        if schedule[mid] <= minute:
            result = mid
            lo = mid
        else:
            hi = mid - 1

    if schedule[lo] <= minute:
        result = lo

    return result

