def classify_grades(grades):
    """Group grades into letter categories with counts and averages."""
    thresholds = [(90, 'A'), (80, 'B'), (70, 'C'), (60, 'D')]
    result = {
        'A': [], 'B': [], 'C': [], 'D': [], 'F': []
    }

    for grade in grades:
        for threshold, letter in thresholds:
            if grade > threshold:
                result[letter].append(grade)
                break
        else:
            result['F'].append(grade)

    summary = {}
    for letter, bucket in result.items():
        if bucket:
            summary[letter] = {
                'count': len(bucket),
                'avg': sum(bucket) / len(bucket)
            }
    return summary

