def convert_units(value, unit, target_unit, default=0.0):
    if value is None:
        return default
    if not isinstance(unit, str) or not isinstance(target_unit, str):
        return default
    if unit.strip() == '' or target_unit.strip() == '':
        return default
    factor = unit_map.get(unit.strip())
    target_factor = unit_map.get(target_unit.strip())
    if factor is None or target_factor is None:
        return default
    return value * (factor / target_factor)

