import math

def retry_backoff(attempts, base_delay, max_delay=10.0):
    if attempts < 0:
        raise ValueError("attempts must be non-negative")
    if base_delay is None or isinstance(base_delay, str):
        if isinstance(base_delay, str) and base_delay == "":
            return max_delay
        raise ValueError("base_delay must be a number")
    delay = base_delay * (2 ** attempts)
    return min(delay, max_delay)

