def parse_recurrence(text, default=None):
    if not isinstance(text, str) or not text.strip():
        return default
    parts = text.split(',')
    if len(parts) != 2:
        raise ValueError("Invalid format")
    freq = parts[0].strip().upper()
    if freq == 'DAILY':
        interval_str = parts[1].strip()
        if not interval_str:
            interval_str = '1'
        try:
            interval = int(interval_str)
        except ValueError:
            raise ValueError("Invalid interval")
        return (freq, interval)
    elif freq == 'WEEKLY':
        days_str = parts[1].strip()
        if days_str == '':
            days = []
        else:
            try:
                days = [int(d) for d in days_str.split()]
            except ValueError:
                raise ValueError("Invalid days")
        return (freq, days)
    else:
        raise ValueError(f"Unknown frequency {freq}")

