def parse_gcode_job(job_data):
    """Parses a G-code job data string into a dictionary of layers and their heights.

    Parameters:
        job_data (str): A string containing G-code commands. Each line should be 'G1 Z<height>' or 'G0 Z<height>'.

    Returns:
        dict: A dictionary where keys are layer heights (floats) and values are the count of commands for that height.

    Behavior for bad input:
        - If job_data is None, return an empty dictionary {}.
        - If job_data is an empty string or only whitespace, return an empty dictionary {}.
        - If job_data is not a string (wrong type), raise a TypeError.
        - If a line in job_data is malformed (does not match expected pattern), skip that line (do not crash).
    """
    if not isinstance(job_data, str):
        raise TypeError("job_data must be a string")

    result = {}
    for line in job_data.splitlines():
        line = line.strip()
        if not line:
            continue
        # Simple parsing: look for Z followed by a number
        parts = line.split()
        if len(parts) >= 2 and parts[0] in ('G1', 'G0'):
            z_part = parts[1]
            if z_part.startswith('Z'):
                try:
                    height = float(z_part[1:])
                    result[height] = result.get(height, 0) + 1
                except ValueError:
                    pass
    return result

