import heapq

def min_meeting_rooms_or(intervals, default=0):
    if intervals is None:
        return default
    if not intervals:
        return default
    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])
    end_times = []
    for start, end in intervals:
        # Free rooms where end time <= current start
