from typing import Optional, List, Tuple

def calculate_track_length(points: Optional[List[Tuple[float, float]]]) -> float:
    if points is None:
        return 0.0
    if not isinstance(points, list):
        raise TypeError("Input must be a list")
    if not points:
        return 0.0

    for p in points:
        if not isinstance(p, tuple):
            raise TypeError("Each point must be a tuple")
        if len(p) != 2:
            raise TypeError("Each point must have exactly two coordinates")
        if not all(isinstance(x, (int, float)) for x in p):
            raise TypeError("Coordinates must be numbers")

    total_dist = 0.0
    for i in range(len(points) - 1):
        p1 = points[i]
        p2 = points[i+1]
        lat1, lon1 = p1
        lat2, lon2 = p2

        # Calculate distance between two points
        d_lat = lat2 - lat1
        d_lon = lon2 - lon1
        a = math.sin(d_lat / 2)**2 + math.cos(lat1) * math.cos(lat2) * math.sin(d_lon / 2)**2
        c = 2 * math.asin(math.sqrt(a))
        total_dist += c

    return total_dist

