def parse_utc_offset(text):
    if text is None or text.strip() == '':
        return 0
    s = text.strip()
    if s == 'Z':
        return 0
    if not s or (s[0] not in '+-' and s[0].isdigit()):
        raise ValueError('Malformed offset')
    try:
        sign = 1 if s[0] == '+' else -1
        body = s[1:]
        if ':' in body:
            parts = body.split(':')
            if len(parts) != 2:
                raise ValueError
            hours, mins = int(parts[0]), int(parts[1])
        else:
            if len(body) != 4 or not body.isdigit():
                raise ValueError
            hours, mins = int(body[:2]), int(body[2:])
        return sign * (hours * 60 + mins)
    except Exception:
        raise ValueError('Malformed offset')

