def compare_semver(a, b, default=0):
    """Compare two semantic version strings.
    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    Returns default if either input is not a valid 'MAJOR.MINOR.PATCH' string.
    """
    def parse(v):
        parts = v.split('.')
        return tuple(int(p) for p in parts)

    pa = parse(a)
    pb = parse(b)

    if pa < pb:
        return -1
    elif pa > pb:
        return 1
    else:
        return 0

reference:
def compare_semver(a, b, default=0):
    def parse(v):
        if not isinstance(v, str):
            return None
        parts = v.strip().split('.')
        if len(parts) != 3:
            return None
        try:
            return tuple(int(p) for p in parts)
        except ValueError:
            return None

    pa = parse(a)
    pb = parse(b)

    if pa is None or pb is None:
        return default

    if pa < pb:
        return -1
    elif pa > pb:
        return 1
    else:
        return 0

