def find_ferry_schedule(schedules, target_hour, target_minute):
    """Find the index of the schedule closest to the target time.
    Schedules is a list of (hour, minute) tuples sorted by time.
    Returns the index of the schedule that is >= (target_hour, target_minute),
    or the index of the last schedule if none are >= target.
    """
    if not schedules:
        return -1
    lo, hi = 0, len(schedules)
    while lo < hi:
        mid = (lo + hi) // 2
        h, m = schedules[mid]
        if (h, m) > (target_hour, target_minute):
            hi = mid
        else:
            lo = mid + 1
    if lo == len(schedules):
        return lo - 1
    return lo

