import collections


class RideQueue:
    """Stores ride requests with 1-based indexing for external access."""
    _items = collections.deque()

    def enqueue(self, ride):
        self._items.append(ride)

    def dequeue(self):
        return self._items.popleft()

    def peek(self, n):
        # n is 1-based index from the front
        if n < 1:
            return None
        try:
            return self._items[n - 1]
        except IndexError:
            return None

    def size(self):
        return len(self._items)

