def parse_showtime(text, default=None):
    """Parse a cinema showtime string 'HH:MM' or 'H:MM' into minutes from midnight.

    Returns default if text is None, empty, whitespace-only, not a string, or malformed.
    """
    if text is None:
        return default
    if not isinstance(text, str):
        return default
    stripped = text.strip()
    if not stripped:
        return default
    parts = stripped.split(':')
    if len(parts) != 2:
        return default
    try:
        hours = int(parts[0])
        minutes = int(parts[1])
    except ValueError:
        return default
    if not (0 <= hours <= 23 and 0 <= minutes <= 59):
        return default
    return hours * 60 + minutes

