from datetime import timedelta


def next_occurrence(start, interval_days, after):
    """Return the first date >= after that occurs every interval_days from start."""
    if after < start:
        return start
    days_diff = (after - start).days
    steps = (days_diff + interval_days - 1) // interval_days
    return start + timedelta(days=steps * interval_days)

