def plan_elevator_stop(requests, default=None):
    if requests is None or not isinstance(requests, list):
        return default
    if not requests:
        return default
    for req in requests:
        if not isinstance(req, tuple) or len(req) != 2:
            return default
        direction, floor = req
        if direction not in ('U', 'D'):
            return default
        if not isinstance(floor, int) or floor < 0:
            return default
    return requests[0][1]

