def normalize(value, min_val, max_val, target_min=0.0, target_max=1.0):
    """
    Linearly scales value from [min_val, max_val] to [target_min, target_max].
    """
    if max_val == min_val:
        return target_min
    ratio = (value - min_val) / (max_val - min_val)
    return target_min + ratio * (target_max - target_min)

