def parse_marathon_splits(text, default=None):
    if text is None or not isinstance(text, str):
        return default
    s = text.strip()
    if not s:
        return default
    try:
        parts = s.split(',')
        result = []
        for p in parts:
            p = p.strip()
            if not p:
                return default
            segs = p.split(':')
            if not segs or not all(seg.isdigit() for seg in segs):
                return default
            total = 0
            for seg in segs:
                total = total * 60 + int(seg)
            result.append(float(total))
        return result
    except Exception:
