def calculate_fare(distance_km, rate_per_km=0.5, default=0.0):
    if distance_km is None:
        return default
    if isinstance(distance_km, str):
        stripped = distance_km.strip()
        if not stripped:
            return default
        try:
            val = float(stripped)
        except ValueError:
            return default
    elif isinstance(distance_km, (int, float)):
        val = float(distance_km)
    else:
        return default
    return val * rate_per_km

