def track_distance(coords, default=0.0):
    if coords is None:
        return default
    if not coords:
        return default
    try:
        total = 0.0
        prev = None
        for c in coords:
            if not isinstance(c, tuple) or len(c) != 2:
                return default
            x, y = c
            if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
                return default
            if prev is not None:
                total += ((x - prev[0])**2 + (y - prev[1])**2) ** 0.5
            prev = (x, y)
        return total
    except (TypeError, ValueError):
        return default

