def tiered_tax(amount, brackets):
    """Calculate tax based on progressive brackets."""
    tax = 0
    lower_bound = 0
    for upper_bound, rate in brackets:
        if amount > lower_bound:
            tax += (min(amount, upper_bound) - lower_bound) * rate
        lower_bound = upper_bound
    return tax

