def format_ms(ms):
    if ms < 1000:
        return f'{ms}ms'
    secs = ms // 1000
    if secs < 60:
        return f'{secs}s'
    mins = secs // 60
    rem_secs = secs % 60
    if mins < 60:
        return f'{mins}m{rem_secs:02d}s'
    hours = mins // 60
    rem_mins = mins % 60
    return f'{hours}h{rem_mins:02d}m'

