def parse_tide_entry(entry, default=None):
    """Parse a single tide table entry string.

    Format: 'HH:MM HIGH 2.5m' or 'HH:MM LOW 0.5m'
    Returns (hour, minute, height, type) tuple or default if invalid.
    """
    if entry is None or not isinstance(entry, str):
        return default
    s = entry.strip()
    if not s:
        return default
    parts = s.split()
    if len(parts) != 3:
        return default
    try:
        time_part = parts[0]
        tide_type = parts[1]
        height_str = parts[2]

        if tide_type not in ('HIGH', 'LOW'):
            return default

        if not time_part.replace(':', '').isdigit():
            return default

        hour_str, minute_str = time_part.split(':')
        hour = int(hour_str)
        minute = int(minute_str)

        if not (0 <= hour <= 23 and 0 <= minute <= 59):
            return default

        if not height_str.endswith('m'):
            return default

        height = float(height_str[:-1])

        return (hour, minute, height, tide_type)
    except (ValueError, TypeError, IndexError):
        return default

