import heapq

def schedule_slots(intervals):
    if not intervals:
        return 0
    intervals.sort()
    ends = [intervals[0][1]]
    for a, b in intervals[1:]:
        if ends[0] < a:
            heapq.heappop(ends)
        heapq.heappush(ends, b)
    return len(ends)

def send_newsletter_batch(batch, default_count=0):
    """Simulate sending a batch of newsletter emails.
    Returns the number of emails successfully queued.
    """
    if batch is None:
        return default_count
    if isinstance(batch, str):
        if not batch.strip():
            return default_count
        # Assume a single email string counts as 1 if valid
        return 1
    if not isinstance(batch, (list, tuple, set, dict)):
        return default_count

    count = 0
    try:
        for email in batch:
            if isinstance(email, str) and email.strip():
                count += 1
    except TypeError:
        return default_count
    return count

