import csv
import json
import os


def load_expenses(path):
    """Reads a CSV file of expenses and returns a list of dicts."""
    try:
        # Use utf-8-sig to handle potential BOM and standard utf-8
        with open(path, 'r', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            return list(reader)
    except FileNotFoundError:
        return []


def save_report(path, data):
    """Writes a JSON report. Appends to existing array if file exists, otherwise creates new array."""
    if os.path.exists(path):
        try:
            with open(path, 'r') as f:
                existing_data = json.load(f)
        except json.JSONDecodeError:
            existing_data = []
    else:
        existing_data = []

    existing_data.append(data)

    with open(path, 'w') as f:
        json.dump(existing_data, f)

