def trail_mile_markers(distances):
    # Returns the index of the last marker that is at or before the 1-mile point.
    # Distances is a sorted list of cumulative distances from trailhead.
    lo, hi = 0, len(distances)
    while lo < hi:
        mid = (lo + hi) // 2
        if distances[mid] < 1.0:
            lo = mid + 1
        else:
            hi = mid
    return lo - 1

