import math

def get_laser_cut_positions(length, step_size):
    if step_size <= 0:
        raise ValueError('step_size must be positive')
    if length <= 0:
        return []
    positions = []
    n = math.floor(length / step_size)
    for i in range(1, n + 1):
        pos = i * step_size
        positions.append(pos)
    return positions

