reference:
def parse_departure(entry, default=None):
    if entry is None:
        return default
    if not isinstance(entry, str):
        return default
    stripped = entry.strip()
    if not stripped:
        return default
    parts = stripped.split(':')
    if len(parts) != 2:
        return default
    try:
        h = int(parts[0])
        m = int(parts[1])
        return (h, m)
    except ValueError:
        return default

